mapper.select:
select t.heartbeat_time,t.heartbeat_time heartbeatTime,t.machine_code,t.machine_code
machineCode,t.location_name,t.location_name locationName,t.cur_layer,t.cur_layer curLayer,t.use_unit,t.use_unit
useUnit,t.maintenance_unit,t.maintenance_unit maintenanceUnit,t.factory_id,t.factory_id
factoryId,t.status_cd,t.status_cd statusCd,t.machine_name,t.machine_name machineName,t.machine_id,t.machine_id
machineId,t.rescue_link,t.rescue_link rescueLink,t.registration_unit,t.registration_unit
registrationUnit,t.state,t.community_id,t.community_id communityId,t.brand,t.create_time createTime,lmf.factory_name factoryName,
sc.name communityName, td.name stateName
from lift_machine t
left join lift_machine_factory lmf on t.factory_id = lmf.factory_id
left join s_community sc on t.community_id = sc.community_id
left join t_dict td on t.state = td.status_cd and td.table_name = 'lift_machine' and td.table_columns = 'state'
where 1 =1 and lmf.status_cd = '0' and sc.status_cd = '0'

    and t.heartbeat_time= #{heartbeatTime}


    and t.machine_code like concat('%', #{machineCode}, '%')


    and t.location_name like concat('%', #{locationName}, '%')


    and t.cur_layer= #{curLayer}


    and t.use_unit= #{useUnit}


    and t.maintenance_unit= #{maintenanceUnit}


    and t.factory_id= #{factoryId}


    and t.status_cd= #{statusCd}


    and t.machine_name like concat('%', #{machineName}, '%')


    and t.machine_id like concat('%', #{machineId}, '%')


    and t.rescue_link= #{rescueLink}


    and t.registration_unit= #{registrationUnit}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.brand like concat('%', #{brand}, '%')

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update lift_machine t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.heartbeat_time= #{heartbeatTime}


    , t.machine_code= #{machineCode}


    , t.location_name= #{locationName}


    , t.cur_layer= #{curLayer}


    , t.use_unit= #{useUnit}


    , t.maintenance_unit= #{maintenanceUnit}


    , t.factory_id= #{factoryId}


    , t.machine_name= #{machineName}


    , t.rescue_link= #{rescueLink}


    , t.registration_unit= #{registrationUnit}


    , t.state= #{state}


    , t.community_id= #{communityId}


    , t.brand= #{brand}

where 1=1

    and t.machine_id= #{machineId}

mapper.select:
select count(1) count
from lift_machine t
where 1 =1

    and DATE_ADD(t.heartbeat_time, INTERVAL 2 MINUTE) < #{heartbeatTime}


    and t.machine_code like concat('%', #{machineCode}, '%')


    and t.location_name like concat('%', #{locationName}, '%')


    and t.cur_layer= #{curLayer}


    and t.use_unit= #{useUnit}


    and t.maintenance_unit= #{maintenanceUnit}


    and t.factory_id= #{factoryId}


    and t.status_cd= #{statusCd}


    and t.machine_name like concat('%', #{machineName}, '%')


    and t.machine_id like concat('%', #{machineId}, '%')


    and t.rescue_link= #{rescueLink}


    and t.registration_unit= #{registrationUnit}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.brand like concat('%', #{brand}, '%')
